// ================= DUSTARA INTERIORS (pack section 15) =================
// Each named walk-in gets its own furnishing, matched by the building's name (dHouse(..., { name })).
// Rooms are the walk-in ellipses (door on +z, back wall at cz - rz). A clear lane runs from the door up the middle to the counter or the centre.
// The three story rooms (Your House, Vashti's lab, the Dustmere Recovery Bay) and the upper floors are full-size places in dplaces.js that reuse these layouts.
const dIn = { Y: 0.07 };
const dFrame = (x, y, z, ry, w = 0.5, h = 0.4, pic) => { const G = grp(x, y, z, ry); add(new THREE.BoxGeometry(w, h, 0.04), D.wood(), [0, 0, 0], [0, 0, 0], null, G); add(new THREE.PlaneGeometry(w * 0.8, h * 0.78), pic || std({ color: "#f0e4cc" }), [0, 0, 0.025], [0, 0, 0], null, G); return G; };
const stairBody = (n, rise, run, z0, y0, w, mat, G) => { const s = new THREE.Shape(); s.moveTo(-z0, 0); for (let k = 0; k < n; k++) { s.lineTo(-z0 + k * run, y0 + (k + 1) * rise); s.lineTo(-z0 + (k + 1) * run, y0 + (k + 1) * rise); } s.lineTo(-z0 + n * run, 0); s.lineTo(-z0, 0); const m = add(new THREE.ExtrudeGeometry(s, { depth: w, bevelEnabled: false }), mat, [-w / 2, 0, 0], [0, Math.PI / 2, 0], null, G); const L = Math.hypot(n * run, n * rise), a = Math.atan2(rise, run); for (const sd of [-1, 1]) add(new THREE.BoxGeometry(0.07, 0.34, L + 0.2), mat, [sd * (w / 2 + 0.035), y0 + n * rise / 2 + 0.12, z0 - n * run / 2], [a, 0, 0], null, G); return m; };
const dStairs = (x, z, ry = 0, n = 7, w = 0.9) => { const G = grp(x, 0, z, ry); for (let k = 0; k < n; k++) add(new THREE.BoxGeometry(w, 0.2, 0.32), D.wood(), [0, 0.1 + k * 0.24, -k * 0.3], [0, 0, 0], null, G); stairBody(n, 0.24, 0.3, 0.15, -0.04, w * 0.98, D.wood(), G); /* closed risers + stringers: no more floating planks (inspection Nov 2026) */ add(new THREE.BoxGeometry(0.06, 1.0, n * 0.32), D.wood(), [w / 2, 0.9 + n * 0.12, -n * 0.15], [-0.65, 0, 0], null, G); return G; };
const dLadder = (x, z, ry = 0, h = 2.6) => { const G = grp(x, 0, z, ry); for (const s of [-0.22, 0.22]) add(new THREE.BoxGeometry(0.05, h, 0.05), D.wood(), [s, h / 2, 0], [0, 0, 0], null, G); for (let y = 0.3; y < h; y += 0.32) add(new THREE.BoxGeometry(0.48, 0.04, 0.04), D.wood(), [0, y, 0], [0, 0, 0], null, G); return G; };
const dCapsule = (x, z) => { const G = grp(x, 0, z); add(olathe([[0.001, 0], [0.22, 0], [0.18, 0.08], [0.06, 0.12], [0.06, 0.62], [0.2, 0.68], [0.2, 0.74], [0.001, 0.74]], 16), D.brass(), [0, 0, 0], [0, 0, 0], null, G); const c = add(new THREE.CapsuleGeometry(0.15, 0.18, 6, 14), std({ color: "#d8f4ff", transparent: true, opacity: 0.45, roughness: 0.05 }), [0, 1.02, 0], [0, 0, 0], null, G); c.name = "nocol"; add(new THREE.SphereGeometry(0.06, 8, 6), MK.glowC("#7ff0e6", 1.2), [0, 1.02, 0], [0, 0, 0], null, G); return G; }; // a plain rounded glass capsule on a brass stand
const dScreen = (x, y, z, ry, w = 0.6, h = 0.4) => { const G = grp(x, y, z, ry); add(new THREE.BoxGeometry(w, h, 0.06), std({ color: "#2a2e34" }), [0, 0, 0], [0, 0, 0], null, G); add(new THREE.PlaneGeometry(w * 0.86, h * 0.8), std({ color: "#102028", emissive: "#2a6a7a", emissiveIntensity: 0.6 }), [0, 0, 0.032], [0, 0, 0], null, G); return G; }; // blank screens
const dEmblem = (x, y, z, ry, s = 0.35) => { const G = grp(x, y, z, ry); add(new THREE.CircleGeometry(s, 24), D.turq(), [0, 0, 0], [0, 0, 0], null, G); const h = new THREE.Shape(); h.moveTo(0, -s * 0.5); h.bezierCurveTo(s * 0.7, -s * 0.05, s * 0.45, s * 0.55, 0, s * 0.2); h.bezierCurveTo(-s * 0.45, s * 0.55, -s * 0.7, -s * 0.05, 0, -s * 0.5); add(new THREE.ShapeGeometry(h), MK.glowC("#ffffff", 0.7), [0, 0, 0.01], [0, 0, 0], null, G); const lf = add(new THREE.SphereGeometry(s * 0.2, 8, 6), MK.glowC("#7ae07a", 0.7), [s * 0.28, s * 0.42, 0.02], [0, 0, 0], null, G); lf.scale.set(0.6, 1.2, 0.2); return G; }; // leaf-and-heart icon, no letters
const dCactusPot = (x, z, s = 0.6) => { D.urn(x, z, s); D.prickly(x, z, s * 0.6); };
const dChime = (x, y, z) => { for (let k = 0; k < 5; k++) add(new THREE.CylinderGeometry(0.015, 0.015, 0.25 + k * 0.05, 5), D.brass(), [x + (k - 2) * 0.06, y - 0.15 - k * 0.025, z]); };
const dPoster = () => FX.M.poster || (FX.M.poster = std({ map: tex(256, 192, (g, W) => { const H2 = 192; const gr = g.createLinearGradient(0, 0, 0, H2); gr.addColorStop(0, "#1a1440"); gr.addColorStop(1, "#c86a48"); g.fillStyle = gr; g.fillRect(0, 0, W, H2); for (let k = 0; k < 14; k++) { const x = R() * W, y = R() * H2 * 0.7; g.strokeStyle = "rgba(255,240,200,0.8)"; g.lineWidth = 2; g.beginPath(); g.moveTo(x, y); g.lineTo(x - 30, y - 22); g.stroke(); g.fillStyle = "#fff4d0"; g.beginPath(); g.arc(x, y, 3, 0, TAU); g.fill(); } g.fillStyle = "#3a1a10"; g.beginPath(); g.moveTo(0, H2); g.lineTo(W * 0.3, H2 * 0.8); g.lineTo(W * 0.6, H2 * 0.86); g.lineTo(W, H2 * 0.75); g.lineTo(W, H2); g.fill(); }) })); // a picture of falling lights, no text
const dRock = (x, y, z, c, s = 0.12) => add(new THREE.DodecahedronGeometry(s, 0), std({ color: c, roughness: 0.6, emissive: c, emissiveIntensity: 0.15 }), [x, y, z], [R(), R(), R()]);
const dSlabs = (x, z, n = 3, crooked = 0) => { for (let k = 0; k < n; k++) { const s = add(new THREE.BoxGeometry(0.5, 0.06, 0.4), D.paleStone(), [x + (R() - 0.5) * crooked, 0.75 + k * 0.065, z + (R() - 0.5) * crooked], [0, (R() - 0.5) * (crooked ? 1.2 : 0.1), (R() - 0.5) * crooked * 0.4]); add(new THREE.BoxGeometry(0.3, 0.01, 0.04), MK.glowC("#7ff0e6", 0.8), [x, 0.79 + k * 0.065, z], [0, 0, 0]).name = "nocol"; } };

