    { const C = grp(cx + m * 0.7, 0, cz + rz * 0.05, Math.PI); add(soft(new THREE.BoxGeometry(1.5, 0.4, 0.7, 2, 1, 2), { warp: 0.03 }), std({ color: "#2a9a96", roughness: 0.9 }), [0, 0.32, 0], [0, 0, 0], null, C); add(soft(new THREE.BoxGeometry(1.5, 0.5, 0.2, 2, 1, 1), { warp: 0.03 }), std({ color: "#2a9a96", roughness: 0.9 }), [0, 0.6, -0.28], [0, 0, 0], null, C); } // the couch faces the TV
