FX.uwNL = (n0) => { if (!TER.low) return; const b = new THREE.Box3(), c = new THREE.Vector3(); for (const o of root.children.slice(n0)) { if (!o.userData.noLift || o.name === "ground" || o.name === "water" || o.name === "grass") continue; if (o.isLight) c.copy(o.position); else { b.setFromObject(o); if (b.isEmpty()) continue; if (BEND(o, b, null)) continue; b.getCenter(c); } const [ux, uz] = unwarp(c.x, c.z); o.position.x += ux - c.x; o.position.z += uz - c.z; if (!o.isLight) { o.userData.__tx = c.x; o.userData.__tz = c.z; TURN(o, ux, uz); } } }; /* terrain fix: noLift pieces built on the grid follow the ground meander like everything liftAll moves */
