  add(new THREE.CylinderGeometry(0.16 * s, 0.2 * s, 6 * s, 8), thMat.woodD(), [-1.5 * s, 3.2 * s, 0.5], [0.4, 0, 0.35], "nocol", G); add(new THREE.CylinderGeometry(0.14 * s, 0.18 * s, 3 * s, 8), thMat.woodD(), [3 * s, 2 * s, 0], [-0.2, 0, -0.5], "nocol", G);
