const thChest = (x, z, ry = 0) => { const G = grp(x, 0, z, ry); add(new THREE.BoxGeometry(0.9, 0.5, 0.6), thMat.wood(), [0, 0.25, 0], [0, 0, 0], null, G); add(new THREE.CylinderGeometry(0.3, 0.3, 0.9, 12, 1, false, 0, Math.PI), thMat.wood(), [0, 0.5, 0], [0, 0, Math.PI / 2], "nocol", G); for (const dx of [-0.32, 0.32]) add(new THREE.BoxGeometry(0.07, 0.82, 0.64), thMat.brass(), [dx, 0.4, 0], [0, 0, 0], "nocol", G); add(new THREE.BoxGeometry(0.16, 0.18, 0.05), thMat.brass(), [0, 0.45, 0.31], [0, 0, 0], "nocol", G); return G; };
const thBench = (x, z, ry = 0) => { const G = grp(x, 0, z, ry); add(new THREE.BoxGeometry(1.6, 0.08, 0.45), thMat.wood(), [0, 0.45, 0], [0, 0, 0], null, G); add(new THREE.BoxGeometry(1.6, 0.4, 0.06), thMat.wood(), [0, 0.7, -0.2], [0, 0, 0], "nocol", G); for (const dx of [-0.7, 0.7]) add(new THREE.BoxGeometry(0.08, 0.45, 0.4), thMat.woodD(), [dx, 0.22, 0], [0, 0, 0], "nocol", G); return G; };
const thBeacon = (x, z, c = "#3aff7a") => { const G = grp(x, 0, z); add(new THREE.CylinderGeometry(0.18, 0.24, 2.2, 8), thMat.white(), [0, 1.1, 0], [0, 0, 0], null, G); add(new THREE.SphereGeometry(0.22, 10, 8), thMat.glow(c, 2), [0, 2.4, 0], [0, 0, 0], "nocol", G); const l = new THREE.PointLight(c, 1.2, 8, 1.6); l.position.set(0, 2.4, 0); G.add(l); return G; };
const thFalls = (x, z, h = 6, w = 3, ry = 0) => { const t = thM("fallsT", () => tex(64, 256, (g, W, Hh) => { g.fillStyle = "#cfefff"; g.fillRect(0, 0, W, Hh); for (let k = 0; k < 120; k++) { g.fillStyle = `rgba(255,255,255,${0.3 + R() * 0.5})`; g.fillRect(R() * W, R() * Hh, 1 + R() * 2, 8 + R() * 30); } }, [1, 1]));
  const G = grp(x, 0, z, ry); add(new THREE.PlaneGeometry(w, h, 1, 1), thM("falls", () => std({ map: t, color: "#ffffff", emissive: "#5ab8e8", emissiveIntensity: 0.35, transparent: true, opacity: 0.85, side: THREE.DoubleSide })), [0, h / 2, 0], [0, 0, 0], "nocol", G);
  for (let k = 0; k < 7; k++) { const m = add(new THREE.SphereGeometry(0.5 + R() * 0.4, 8, 6), thM("foam", () => std({ color: "#ffffff", transparent: true, opacity: 0.7 })), [(R() - 0.5) * w, 0.1, 0.4 + R() * 0.6], [0, 0, 0], "nocol", G); m.scale.y = 0.4; } return G; };
const thTelescope = (x, z, ry = 0) => { const G = grp(x, 0, z, ry); for (let k = 0; k < 3; k++) { const a = (k / 3) * TAU; add(new THREE.CylinderGeometry(0.03, 0.03, 1.3, 5), thMat.woodD(), [Math.cos(a) * 0.25, 0.6, Math.sin(a) * 0.25], [Math.sin(a) * 0.25, 0, -Math.cos(a) * 0.25], "nocol", G); } add(new THREE.CylinderGeometry(0.08, 0.12, 1.2, 12), thMat.brass(), [0, 1.35, 0.1], [1.2, 0, 0], null, G); return G; };
