  for (const s of [-1, 1]) for (let z = -d / 2 + 2.2; z < d / 2 - 1.5; z += 3) { nnBx("carve", O, s * (w / 2 - 0.42), 0.6, z, 0.36, H1, 0.9, stc(O, 54)); gyGlyph(gyAt(O, s * (w / 2 - 0.22), z), 0, 5.2, 0, 0.4, 0.6, s * Math.PI / 2, GYC.turq); }
